SELECT cs.canonical_smiles, sub.compound_name AS substrate_compound_name, par.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m INNER JOIN compound_records sub ON m.substrate_record_id = sub.record_id INNER JOIN compound_records par ON m.drug_record_id = par.record_id INNER JOIN compound_structures cs ON par.molregno = cs.molregno WHERE m.organism = 'Callithrix jacchus' ORDER BY cs.canonical_smiles ASC, sub.compound_name ASC, par.compound_name ASC, m.met_conversion ASC, m.pathway_key ASC, m.organism ASC, m.enzyme_name ASC LIMIT 200
